#!/usr/bin/env bash
set -euo pipefail

# Applies the Home page "Blush & Ink" revamp (tailwind tokens, StorefrontLayout
# canvas/header, Home.tsx surfaces + mobile carousel + section-gap tightening,
# index.css utilities) to a fresh clone of go-website, on a new branch, ready
# for you to push and open a PR from.
#
# Usage: run from anywhere with the go-website repo NOT already cloned here:
#   bash apply_home_blush_revamp.sh
# It clones a fresh copy into ./go-website, so run it somewhere new (e.g. a
# clean directory in your Codespace).

REPO_URL="https://github.com/yoosuf0806/go-website.git"
BRANCH="claude/home-blush-revamp"

if [ -d go-website ]; then
  echo "A ./go-website directory already exists here — remove or rename it first." >&2
  exit 1
fi

echo "Cloning fresh main..."
git clone "$REPO_URL" go-website
cd go-website
git checkout -b "$BRANCH"

echo "Applying patch..."
base64 -d <<'PATCH_B64' | git am

PATCH_B64

echo
echo "Patch applied cleanly on branch $BRANCH."
echo "Next steps:"
echo "  1. git push -u origin $BRANCH"
echo "  2. Open a PR: https://github.com/yoosuf0806/go-website/compare/main...$BRANCH"
